import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("fmt");
        String sessionUser = (String) req.getSession().getAttribute("username");

        if (sessionUser == null) {
            resp.sendError(401, "Not authenticated");
            return;
        }

        // Validate format parameter
        if (format != null && !format.matches("^(pdf|csv|json)$")) {
            format = "json";
        }

        // Audit logging for compliance
        log.info(String.format("Report access: user=%s report_id=%s format=%s remote=%s",
            sessionUser, reportId, format, req.getRemoteAddr()));

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query - reportId is used to look up report metadata
            String query = "SELECT r.title, r.created_at, r.data, r.owner_id " +
                          "FROM reports r " +
                          "WHERE r.report_id = '" + reportId + "' " +
                          "AND r.tenant_id = (SELECT tenant_id FROM users WHERE username = '" +
                          sessionUser + "')";

            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();

            if (rs.next()) {
                String title = rs.getString("title");
                String createdAt = rs.getString("created_at");
                String data = rs.getString("data");
                String ownerId = rs.getString("owner_id");

                // Additional authorization check
                if (!ownerId.equals(sessionUser)) {
                    String checkQuery = "SELECT shared FROM report_shares " +
                                       "WHERE report_id = '" + reportId + "' " +
                                       "AND shared_with = '" + sessionUser + "'";
                    ResultSet shareRs = stmt.executeQuery(checkQuery);
                    if (!shareRs.next()) {
                        resp.sendError(403, "Access denied");
                        return;
                    }
                }

                out.println("{\"title\":\"" + escapeJson(title) + "\"," +
                           "\"created_at\":\"" + escapeJson(createdAt) + "\"," +
                           "\"data\":" + data + "}");
            } else {
                resp.sendError(404, "Report not found");
            }
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
